import{_ as t,o as i,c as l,ae as o}from"./chunks/framework.RRduUuAx.js";const b=JSON.parse('{"title":"Pixiu 내역 가져오기","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/07-pixiu-bill-import-guide.md","filePath":"v1/ko/guide/07-pixiu-bill-import-guide.md"}'),r={name:"v1/ko/guide/07-pixiu-bill-import-guide.md"};function e(d,a,n,h,s,u){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="pixiu-내역-가져오기" tabindex="-1">Pixiu 내역 가져오기 <a class="header-anchor" href="#pixiu-내역-가져오기" aria-label="Permalink to &quot;Pixiu 내역 가져오기&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>이 가이드는 <strong>Pixiu</strong>에서 내보낸 거래 내역(CSV)을 <strong>Koala</strong>로 가져오는 방법을 안내합니다.</p><p>Koala는 현재 <strong>Pixiu CSV 내보내기 파일</strong>만 지원합니다(CSV 전용).</p><hr><h2 id="📱-1단계-pixiu에서-내역-내보내기" tabindex="-1">📱 1단계: Pixiu에서 내역 내보내기 <a class="header-anchor" href="#📱-1단계-pixiu에서-내역-내보내기" aria-label="Permalink to &quot;📱 1단계: Pixiu에서 내역 내보내기&quot;">​</a></h2><p>Pixiu는 버전에 따라 메뉴명이 조금 다를 수 있지만 흐름은 같습니다. “데이터 내보내기/내역 내보내기”에서 기간을 선택한 뒤 CSV로 저장하세요.</p><h3 id="단계-1-내보내기-메뉴-찾기" tabindex="-1">단계 1: 내보내기 메뉴 찾기 <a class="header-anchor" href="#단계-1-내보내기-메뉴-찾기" aria-label="Permalink to &quot;단계 1: 내보내기 메뉴 찾기&quot;">​</a></h3><ol><li>Pixiu 앱을 엽니다</li><li><strong>我的</strong>로 이동합니다</li><li><strong>数据导出 / 导出账单</strong>(표기 다를 수 있음)을 찾습니다</li></ol><h3 id="단계-2-기간-선택" tabindex="-1">단계 2: 기간 선택 <a class="header-anchor" href="#단계-2-기간-선택" aria-label="Permalink to &quot;단계 2: 기간 선택&quot;">​</a></h3><ol><li>기간(예: 최근 1개월/최근 3개월)을 선택합니다</li><li>확인 후 내보내기를 시작합니다</li></ol><blockquote><p>💡 팁:</p><ul><li>한 번에 3개월 이내로 내보내는 것을 권장합니다(파일이 커지면 파싱이 느려질 수 있습니다).</li><li>데이터가 많다면 여러 파일로 나눠서 내보낸 뒤 순서대로 가져오세요.</li></ul></blockquote><h3 id="단계-3-csv로-저장" tabindex="-1">단계 3: CSV로 저장 <a class="header-anchor" href="#단계-3-csv로-저장" aria-label="Permalink to &quot;단계 3: CSV로 저장&quot;">​</a></h3><ol><li>내보내기 형식은 <strong>CSV</strong>를 선택합니다</li><li>파일을 기기에 저장합니다(공유 → 파일에 저장 등)</li><li>저장 위치를 기억해 둡니다</li></ol><hr><h2 id="📱-2단계-koala로-가져오기" tabindex="-1">📱 2단계: Koala로 가져오기 <a class="header-anchor" href="#📱-2단계-koala로-가져오기" aria-label="Permalink to &quot;📱 2단계: Koala로 가져오기&quot;">​</a></h2><h3 id="단계-1-가져오기-화면-열기" tabindex="-1">단계 1: 가져오기 화면 열기 <a class="header-anchor" href="#단계-1-가져오기-화면-열기" aria-label="Permalink to &quot;단계 1: 가져오기 화면 열기&quot;">​</a></h3><ol><li>Koala 앱을 엽니다</li><li>하단의 <strong>설정</strong>을 탭합니다</li><li><strong>내역 가져오기</strong>를 찾아 들어갑니다</li></ol><h3 id="단계-2-가져오기-소스-선택" tabindex="-1">단계 2: 가져오기 소스 선택 <a class="header-anchor" href="#단계-2-가져오기-소스-선택" aria-label="Permalink to &quot;단계 2: 가져오기 소스 선택&quot;">​</a></h3><ol><li><strong>가져오기 소스</strong>를 탭합니다</li><li><strong>Pixiu</strong>를 선택합니다</li></ol><blockquote><p>⚠️ 중요: 반드시 Pixiu를 선택해야 합니다. 소스를 잘못 선택하면 검증이 실패하거나 필드가 잘못 읽힐 수 있습니다.</p></blockquote><h3 id="단계-3-파일-선택" tabindex="-1">단계 3: 파일 선택 <a class="header-anchor" href="#단계-3-파일-선택" aria-label="Permalink to &quot;단계 3: 파일 선택&quot;">​</a></h3><ol><li><strong>파일 경로</strong>를 탭합니다</li><li>Pixiu에서 내보낸 <strong>CSV</strong>를 선택합니다</li><li>파일명이 표시되는지 확인합니다</li></ol><h3 id="단계-4-장부-연결" tabindex="-1">단계 4: 장부 연결 <a class="header-anchor" href="#단계-4-장부-연결" aria-label="Permalink to &quot;단계 4: 장부 연결&quot;">​</a></h3><ol><li><strong>장부 연결</strong>을 탭합니다</li><li>가져올 장부를 선택합니다</li></ol><h3 id="단계-5-파싱-및-미리보기" tabindex="-1">단계 5: 파싱 및 미리보기 <a class="header-anchor" href="#단계-5-파싱-및-미리보기" aria-label="Permalink to &quot;단계 5: 파싱 및 미리보기&quot;">​</a></h3><ol><li>우측 상단의 <strong>파싱</strong>을 탭합니다</li><li>파싱 성공 시 미리보기 화면으로 이동합니다</li><li>단건 수정/삭제 또는 유효하지 않은 항목 일괄 건너뛰기가 가능합니다</li></ol><h3 id="단계-6-가져오기-실행" tabindex="-1">단계 6: 가져오기 실행 <a class="header-anchor" href="#단계-6-가져오기-실행" aria-label="Permalink to &quot;단계 6: 가져오기 실행&quot;">​</a></h3><ol><li>확인이 끝나면 <strong>가져오기</strong>를 탭합니다</li><li>완료될 때까지 기다립니다</li></ol><hr><h2 id="📋-pixiu-csv-형식-참고" tabindex="-1">📋 Pixiu CSV 형식(참고) <a class="header-anchor" href="#📋-pixiu-csv-형식-참고" aria-label="Permalink to &quot;📋 Pixiu CSV 형식(참고)&quot;">​</a></h2><p>Koala는 Pixiu CSV를 아래 기준으로 검증합니다.</p><ul><li>1행은 헤더여야 합니다</li><li>헤더 열 수는 <strong>10열</strong>이어야 합니다</li><li>구분자는 쉼표 <code>,</code> 입니다(표준 CSV)</li></ul><h3 id="열-정의-순서" tabindex="-1">열 정의(순서) <a class="header-anchor" href="#열-정의-순서" aria-label="Permalink to &quot;열 정의(순서)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>열</th><th>의미</th><th>설명</th></tr></thead><tbody><tr><td>1</td><td>날짜</td><td><code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code> 지원. 연도는 2016 이상이어야 하며, 아니면 유효하지 않은 날짜로 처리됩니다</td></tr><tr><td>2</td><td>상위 분류</td><td>Koala의 상위 카테고리명 매칭에 사용됩니다</td></tr><tr><td>3</td><td>유형</td><td>“支出”(지출) 또는 “收入”(수입) 키워드를 포함해야 합니다. “收入”이 포함되면 수입으로, 그 외는 지출로 가져옵니다</td></tr><tr><td>4</td><td>하위 분류</td><td>Koala의 하위 카테고리명 매칭에 사용됩니다</td></tr><tr><td>5</td><td>유입 금액</td><td>수입 금액 열(<code>-</code> 포함 가능, 가져오기 시 부호는 제거됩니다)</td></tr><tr><td>6</td><td>유출 금액</td><td>지출 금액 열(<code>-</code> 포함 가능, 가져오기 시 부호는 제거됩니다)</td></tr><tr><td>7</td><td>통화 코드</td><td><code>CNY</code> / <code>USD</code> 등. 비어 있으면 장부 기본 통화를 사용합니다</td></tr><tr><td>8</td><td>계정</td><td>계정명(이름으로 매칭, 없으면 가져오기 중 생성될 수 있음)</td></tr><tr><td>9</td><td>태그</td><td>여러 태그는 쉼표로 구분(<code>,</code>), 중국어 쉼표 <code>，</code>도 지원</td></tr><tr><td>10</td><td>메모</td><td>메모 텍스트</td></tr></tbody></table><h3 id="koala로의-매핑-개요" tabindex="-1">Koala로의 매핑(개요) <a class="header-anchor" href="#koala로의-매핑-개요" aria-label="Permalink to &quot;Koala로의 매핑(개요)&quot;">​</a></h3><ul><li>날짜 → 날짜</li><li>유형 → 수입/지출</li><li>상위+하위 분류 → 카테고리(매칭 실패 시 미리보기에서 “미완성”으로 표시됨)</li><li>유입/유출 금액 → 금액(유형에 따라 참조 열이 결정됨)</li><li>계정 → 계정</li><li>태그 → 태그(이름으로 매칭/생성 후 연결)</li><li>메모 → 메모</li><li>통화 코드 → 통화(코드로 매칭, 실패 시 장부 통화로 대체)</li></ul><hr><h2 id="⚠️-유의사항" tabindex="-1">⚠️ 유의사항 <a class="header-anchor" href="#⚠️-유의사항" aria-label="Permalink to &quot;⚠️ 유의사항&quot;">​</a></h2><ol><li><strong>자동 중복 제거 없음</strong>: 같은 파일을 두 번 가져오면 중복 내역이 생성됩니다. 동일 기간을 반복해서 가져오지 않도록 주의하세요.</li><li><strong>카테고리 매칭</strong>: “상위+하위” 이름으로 매칭합니다. 매칭되지 않으면 미리보기에서 수정 후 가져오세요.</li><li><strong>계정 유효성</strong>: 계정명이 비어 있거나 기호만 있는 경우 무효로 처리되어 보완이 필요할 수 있습니다.</li><li><strong>인코딩</strong>: UTF-8/GBK를 지원합니다. 글자가 깨지면 UTF-8로 다시 내보내거나 인코딩을 변환해 다시 시도하세요.</li></ol><hr><h2 id="🔧-자주-묻는-질문" tabindex="-1">🔧 자주 묻는 질문 <a class="header-anchor" href="#🔧-자주-묻는-질문" aria-label="Permalink to &quot;🔧 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-헤더-열-수가-맞지-않아요" tabindex="-1">Q1: “헤더 열 수가 맞지 않아요”. <a class="header-anchor" href="#q1-헤더-열-수가-맞지-않아요" aria-label="Permalink to &quot;Q1: “헤더 열 수가 맞지 않아요”.&quot;">​</a></h3><p>CSV 첫 줄 헤더가 <strong>10열</strong>인지 확인하세요. 흔한 원인:</p><ol><li>Pixiu에서 내보낸 파일이 아님</li><li>Excel/WPS에서 편집하면서 구분자가 늘어나 열 수가 바뀜</li><li>호환되지 않는 CSV로 저장(예: 세미콜론 구분)</li></ol><h3 id="q2-금액이-0이-되거나-이상합니다" tabindex="-1">Q2: 금액이 0이 되거나 이상합니다. <a class="header-anchor" href="#q2-금액이-0이-되거나-이상합니다" aria-label="Permalink to &quot;Q2: 금액이 0이 되거나 이상합니다.&quot;">​</a></h3><p>확인:</p><ol><li>“유형” 열에 “支出/收入” 키워드가 포함되어 있는지(유입/유출 중 어떤 열을 읽을지 결정)</li><li>해당 금액 열이 숫자 형식인지(<code>-</code>는 허용, 가져오기 시 제거)</li></ol><h3 id="q3-카테고리가-매칭되지-않습니다" tabindex="-1">Q3: 카테고리가 매칭되지 않습니다. <a class="header-anchor" href="#q3-카테고리가-매칭되지-않습니다" aria-label="Permalink to &quot;Q3: 카테고리가 매칭되지 않습니다.&quot;">​</a></h3><p>미리보기에서 단건으로 올바른 카테고리를 선택해 주세요. 또는 Koala에 Pixiu 내보내기와 같은 이름의 카테고리를 먼저 만든 뒤 다시 파싱하세요.</p><hr><p><strong>마지막 업데이트</strong>: 2026년 5월</p>',52)])])}const x=t(r,[["render",e]]);export{b as __pageData,x as default};
